interface Users {
	find(id: string): User | null;
}

class Logged implements Users {
	constructor(private readonly inner: Users) {}
	find(id: string): User | null {
		console.log(`find ${id}`);
		return this.inner.find(id);
	}
}

class Cached implements Users {
	private readonly seen = new Map<string, User | null>();
	constructor(private readonly inner: Users) {}
	find(id: string): User | null {
		if (!this.seen.has(id)) this.seen.set(id, this.inner.find(id));
		return this.seen.get(id) ?? null;
	}
}

const users: Users = new Logged(new Cached(new SqlUsers()));

