interface Products {
	find(id: string): Product | null;
	save(product: Product): void;
}

class CachedProducts implements Products {
	private readonly seen = new Map<string, Product | null>();
	constructor(private readonly inner: Products) {}

	find(id: string): Product | null {
		if (!this.seen.has(id)) this.seen.set(id, this.inner.find(id));
		return this.seen.get(id) ?? null;
	}

	save(product: Product): void {
		this.inner.save(product);
	}
}

